# Or even better, this comprehensive version:
def aggregate_by_category(datasets, **context):
    import pandas as pd
    from datetime import datetime

    orders = pd.DataFrame(datasets['extrair_orders'])

    if orders.empty:
        return []

    # Convert numeric columns safely
    for col in ['order_amount', 'discount_amount', 'tax_amount']:
        if col in orders.columns:
            orders[col] = pd.to_numeric(orders[col], errors='coerce').fillna(0.0)

    # Aggregation by category
    category_summary = orders.groupby('product_category').agg({
        'order_amount': ['sum', 'mean', 'count'],
        'discount_amount': 'sum',
        'tax_amount': 'sum'
    }).round(2)

    # Flatten columns
    category_summary.columns = ['_'.join(col).strip() for col in category_summary.columns]
    category_summary = category_summary.reset_index()

    # SAFE context access - this is the key fix
    processing_date = context.get('ds')
    if not processing_date:
        execution_date = context.get('execution_date')
        if execution_date:
            processing_date = execution_date.strftime('%Y-%m-%d')
        else:
            processing_date = datetime.now().strftime('%Y-%m-%d')

    category_summary['processing_date'] = processing_date
    category_summary['total_categories'] = len(category_summary)

    return category_summary.to_dict('records')
